import os
import json
import random

class BaseTask:
    # These must be overridden by child classes
    CONFIG_PATH = None  
    BASE_PROMPT = None
    OBJECT_NAMES = []

    def __init__(self, client, collector, skills, randomizer, prompt_variations=None):
        self.client = client
        self.collector = collector
        self.skills = skills  # Your new RobotSkills helper class
        self.randomizer = randomizer
        self.is_success = False
        
        # Store the base prompt and any LLM variations generated by main_collect
        self.prompt_variations = prompt_variations or [self.BASE_PROMPT]
        
        # Pick one variation randomly for this specific episode
        self.episode_prompt = random.choice(self.prompt_variations)

    def setup_environment(self):
        """Set specific environment characteristics of the env like physics dynamics, etc."""
        raise NotImplementedError("Tasks must implement setup_environment()")

    def object_randomizer(self):
        """Randomize position of objects of the scene"""
        raise NotImplementedError("Tasks must implement object_randomizer()")
    
    def execute_expert(self):
        """The hardcoded sequence of waypoints and skills."""
        raise NotImplementedError("Tasks must implement execute_expert()")

    def check_success(self) -> bool:
        """Evaluate simulation state to determine if the task was solved."""
        raise NotImplementedError("Tasks must implement check_success()")

    def save_metadata(self):
        """Saves the language instruction and task config to the episode's directory."""
        if not self.collector.success:
            return 
            
        metadata = {
            "task_name": self.__class__.__name__,
            "base_prompt": self.BASE_PROMPT,
            "episode_prompt": self.episode_prompt,
            "all_variations": self.prompt_variations,
            "config_path": self.CONFIG_PATH,   # <--- NEW: Save the config path
            "object_names": self.OBJECT_NAMES  # <--- NEW: Save the object names
        }
        gripper_profile = getattr(self, "GRIPPER_PROFILE", None)
        if gripper_profile is not None:
            metadata["gripper_controller_profile"] = gripper_profile
        
        meta_path = os.path.join(self.collector.save_dir, "metadata.json")
        with open(meta_path, "w") as f:
            json.dump(metadata, f, indent=4)

    def run(self):
        """The standardized execution loop."""
        self.setup_environment()
        
        if self.randomizer:
            self.object_randomizer()
        
        # Signal collector to start tracking if needed
        self.collector.start()
        
        self.execute_expert()
        
        self.is_success = self.check_success()
        self.collector.success = self.is_success
        
        self.collector.stop()
        
        
        # Save state data and metadata
        self.collector.save()
        self.save_metadata()
        
        return self.is_success
